style.css:
@-moz-document domain("roblox.com") {
:root {
    --custom-background: url("https://www.pinterest.com/pin/970173944744981184/");
  }

  html,
  body,
  #container-main,
  .content,
  .container-main {
    background-color: transparent !important;
  }

  body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -9999;

    background-image:
      linear-gradient(rgba(0, 0, 0, 0.35), rgba(0, 0, 0, 0.35)),
      var(--custom-background);
    background-position: center;
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
  }

  /* Makes Roblox panels slightly transparent */
  .section-content,
  .game-card,
  .game-card-container,
  .container-list,
  .profile-header,
  .profile-about,
  .rbx-tabs-horizontal,
  .stack-row,
  .stack-list {
    background-color: rgba(25, 27, 29, 0.82) !important;
    backdrop-filter: blur(7px);
    border-radius: 8px;
  }
}
